def install(owner):
    if owner.name!='D_E1M8':return
    old=next(z for z in owner.zones if z.notes and z.notes[0].preset==(0,52))
    notes=[n for n in owner.notes if n.z is old];owner.zones.remove(old)
    keys={55:(55,56),60:(60,62),63:(63,)}
    for key,rate,peak,encoded in DATA:
        raw=zlib.decompress(base64.b85decode(encoded));z=copy.copy(old)
        z.notes=[n for n in notes if n.key in keys[key]]
        z.name=f'p52/gm_capture_k{key}';z.kind='attack';z.loop_len=2048
        z.attack=1024/rate;z.nat=z.nat_len=0.;z.morph_basis=None;z.r=z.notes[0].r
        for n in z.notes:
            sp=2**((n.key-key)/12);n.freqs=[(t,v*sp/n.sp) for t,v in n.freqs];n.sp=sp;n.z=z
        z.s_mid=1.;z.s_min=min(n.sp for n in z.notes);z.s_max=max(n.sp for n in z.notes)
        owner.finish(z,[(v-128)*peak/127 for v in raw[:1024]],[(v-128)*peak/127 for v in raw[1024:]],rate)
        owner.zones.append(z)
    owner.layout()
